    }

    ll ans = 0;
    int pos = 0;
    rep(i, N) {
        auto it = s.lower_bound(pos);
        int next;
        if (it == s.begin()) {
            next = *it;
        } else if (it == s.end()) {
            next = *--it;
        } else {
            int cand1 = *it;
            int cand2 = *--it;
            if (abs(cand1 - pos) < abs(cand2 - pos)) {
                next = cand1;
            } else {
                next = cand2;
            }
        }
        ans += abs(next - pos);
        s.erase(next);
        pos = next;
    }
    cout << ans << endl;
    return 0;
}

