bool isok (ll mid, ll N, ll K, vector<ll> &A) {
    ll nk = 0;
    for (ll i = 1; i <= N; i++) {
        if (A.at(i) < mid) {
            nk += (mid - A.at(i) + i - 1) / i;
            if (nk > K) return false;
        }
    }
    return nk <= K;
}

