    }

    ll ok = 1;
    ll ng = A.at(1) + K + 1;

    while (ng - ok > 1) {
        ll mid = (ok + ng) / 2;
        if (isok(mid, N, K, A)) {
            ok = mid;
        } else {
            ng = mid;
        }
    }
    cout << ok << endl;
}

